$u="$env:USERDOMAIN\$env:USERNAME";$pw=Read-Host "Windows password for $u" -AsSecureString;$p=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($pw);try{$plain=[Runtime.InteropServices.Marshal]::PtrToStringBSTR($p)}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($p)};$k='HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon';Set-ItemProperty $k AutoAdminLogon '1';Set-ItemProperty $k DefaultUserName $env:USERNAME;Set-ItemProperty $k DefaultDomainName $env:USERDOMAIN;Set-ItemProperty $k DefaultPassword $plain;Write-Host 'Automatic sign-in enabled. Windows stores this password in Winlogon; use only on the dedicated kiosk account.'
